    @Test
    void requestId同参重放原结果异参409且timingId双重幂等() {
        createRace();
        registerRunner("a", 10_000L, 1, "req-a");
        configure(2, "req-cfg", "c1", "1", "c2", "2");

        SubmitTimingRequest req =
                new SubmitTimingRequest("t-same", "c1", 100L, 3, "req-submit");
        ServiceResult first = raceService.submitTiming(RACE, "a", req);
        ServiceResult replay = raceService.submitTiming(RACE, "a", req);
        assertThat(replay.status()).isEqualTo(first.status());
        // requestId 重放返回的是原响应体 JSON（JsonNode），按 JSON 文本比对
        assertThat(json(replay.body())).isEqualTo(json(first.body()));
        // 重放不重复推进版本（仍为 v4）
        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(4);

        // 同 requestId 异参 -> 409
        assertThatThrownBy(() -> raceService.submitTiming(RACE, "a",
                new SubmitTimingRequest("t-other", "c1", 200L, 3, "req-submit")))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("requestId");

        // 同 timingId 异参（即使换新 requestId）-> 409
        assertThatThrownBy(() -> raceService.submitTiming(RACE, "a",
                new SubmitTimingRequest("t-same", "c2", 200L, 4, "req-submit-other")))
                .isInstanceOf(ConflictException.class)
                .hasMessageContaining("timingId");

        // 同 timingId 同参但新 requestId：作为分段重放返回原结果，不新增记录不推进版本
        ServiceResult timingReplay = raceService.submitTiming(RACE, "a",
                new SubmitTimingRequest("t-same", "c1", 100L, 999, "req-replay-timing"));
        assertThat(timingReplay.status()).isEqualTo(201);
        assertThat(((CheckpointTimingResponse) timingReplay.body()).elapsedMillis()).isEqualTo(100L);
        assertThat(repository.findRace(RACE).orElseThrow().version()).isEqualTo(4);
        assertThat(repository.findAllTimings(RACE)).hasSize(1);
    }

    @Test
    void 业务失败不占用requestId键() {
        createRace();
        registerRunner("a", 10_000L, 1, "req-a");
        configure(2, "req-cfg", "c1", "1");

        // 错误版本提交，业务失败回滚不占键
        assertThatThrownBy(() -> submit("a", "t-1", "c1", 100L, 999, "req-t1"))
                .isInstanceOf(ConflictException.class);
        assertThat(repository.findIdempotency("req-t1")).isEmpty();
        // 同 requestId 用正确版本重试成功
        ServiceResult retry = raceService.submitTiming(RACE, "a",
                new SubmitTimingRequest("t-1", "c1", 100L, 3, "req-t1"));
        assertThat(retry.status()).isEqualTo(201);
    }

    @Test
    void 版本冲突串行化分段与封榜竞争() throws Exception {
        createRace();
        registerRunner("a", 10_000L, 1, "req-a");
        configure(2, "req-cfg", "c1", "1"); // 当前版本 3

        int threads = 8;
        java.util.concurrent.ExecutorService pool =
                java.util.concurrent.Executors.newFixedThreadPool(threads);
        java.util.concurrent.CountDownLatch start = new java.util.concurrent.CountDownLatch(1);
        java.util.concurrent.atomic.AtomicInteger timingOk = new java.util.concurrent.atomic.AtomicInteger();
        java.util.concurrent.atomic.AtomicInteger sealOk = new java.util.concurrent.atomic.AtomicInteger();
        java.util.concurrent.atomic.AtomicInteger conflicts = new java.util.concurrent.atomic.AtomicInteger();
        try {
            var futures = new java.util.ArrayList<java.util.concurrent.Future<?>>();
            for (int i = 0; i < threads; i++) {
                final int index = i;
                futures.add(pool.submit(() -> {
                    start.await();
                    try {
                        if (index % 2 == 0) {
                            raceService.submitTiming(RACE, "a", new SubmitTimingRequest(
                                    "t-conc-" + index, "c1", 100L + index, 3, "req-conc-" + index));
                            timingOk.incrementAndGet();
                        } else {
                            raceService.sealRace(RACE, new SealRaceRequest(3, "req-seal-" + index));
                            sealOk.incrementAndGet();
                        }
                    } catch (ConflictException ex) {
                        conflicts.incrementAndGet();
                    }
                    return null;
                }));
            }
            start.countDown();
            for (java.util.concurrent.Future<?> future : futures) {
                future.get(30, java.util.concurrent.TimeUnit.SECONDS);
            }
        } finally {
            pool.shutdownNow();
        }

        // 同一版本只允许一个写成功（要么一条分段，要么封榜）
        assertThat(timingOk.get() + sealOk.get()).isEqualTo(1);
        assertThat(conflicts.get()).isEqualTo(threads - 1);
        RaceRow race = repository.findRace(RACE).orElseThrow();
        assertThat(race.version()).isEqualTo(4);
        if (sealOk.get() == 1) {
            assertThat(race.status()).isEqualTo(RaceStatus.SEALED);
            assertThat(repository.findAllTimings(RACE)).isEmpty();
        } else {
            assertThat(race.status()).isEqualTo(RaceStatus.OPEN);
            assertThat(repository.findAllTimings(RACE)).hasSize(1);
        }
    }
}

package com.example.starter.race.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 提交选手检查点通过记录请求。
 *
 * @param timingId        全局唯一分段记录ID（第二层幂等键）
 * @param checkpointCode  通过的检查点代码
 * @param elapsedMillis   通过累计耗时（毫秒，1~86400000），必须小于该选手原始完赛耗时
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（写操作幂等键）
 */
public record SubmitTimingRequest(
        @NotBlank String timingId,
        @NotBlank String checkpointCode,
        @NotNull @Positive @Max(86_400_000L) Long elapsedMillis,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 登记选手请求；不传 finishTimeMs 时该选手计时缺失（UNTIMED）。
 *
 * @param bib             参赛号，赛事内唯一
 * @param finishTimeMs    原始完赛耗时（毫秒，1~86400000）；可空表示暂未计时
 * @param expectedVersion 客户端所见赛事版本，服务端据此做乐观并发控制
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record RegisterRunnerRequest(
        @NotBlank String bib,
        @Positive Long finishTimeMs,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单个选手在单个检查点上的分段明细。
 *
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序，从1连续递增
 * @param elapsedMillis  通过累计耗时（毫秒）；尚未通过（缺失检查点）为 null
 * @param timingId       分段记录ID；尚未通过为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CheckpointPassResponse(
        String checkpointCode,
        int position,
        Long elapsedMillis,
        String timingId
) {
}

package com.example.starter.race.api;

/**
 * 分段通过记录响应。
 *
 * @param timingId       全局唯一分段记录ID
 * @param bib            选手参赛号
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序，从1连续递增
 * @param elapsedMillis  通过该检查点的累计耗时（毫秒）
 * @param createdAt      提交时间，Unix毫秒时间戳
 */
public record CheckpointTimingResponse(
        String timingId,
        String bib,
        String checkpointCode,
        int position,
        long elapsedMillis,
        long createdAt
) {
}

package com.example.starter.race.api;

import com.example.starter.race.support.AbstractRaceH2Test;
import com.example.starter.race.support.FixedClockTestConfig;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 分段计时能力的端到端 HTTP 测试：真实 Spring MVC + Service + H2，
 * 覆盖配置、乱序提交、422 相邻约束、漏点排名、只读查询与封榜固化。
 */
@SpringBootTest
@AutoConfigureMockMvc
@Import(FixedClockTestConfig.class)
class RaceCheckpointApiH2Test extends AbstractRaceH2Test {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void 分段配置提交漏点到封榜全链路() throws Exception {
        mockMvc.perform(post("/api/races")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"raceId":"r","requestId":"c0"}
                                """))
                .andExpect(status().isCreated());

        // 两个选手：a 完赛 5000，b 完赛 9000（版本到3）
        mockMvc.perform(post("/api/races/r/runners")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"bib":"a","finishTimeMs":5000,"expectedVersion":1,"requestId":"c1"}
                                """))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/races/r/runners")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"bib":"b","finishTimeMs":9000,"expectedVersion":2,"requestId":"c2"}
                                """))
                .andExpect(status().isCreated());

        // 配置3个检查点（顺序故意打乱，服务端按 position 返回）
        mockMvc.perform(post("/api/races/r/checkpoints")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"checkpoints":[
                                  {"checkpointCode":"p1","position":1},
                                  {"checkpointCode":"p3","position":3},
                                  {"checkpointCode":"p2","position":2}],
                                 "expectedVersion":3,"requestId":"c3"}
                                """))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.version").value(4))
                .andExpect(jsonPath("$.checkpoints[0].checkpointCode").value("p1"))
                .andExpect(jsonPath("$.checkpoints[2].checkpointCode").value("p3"));

        // 乱序提交：b 先 p3 再 p1
        mockMvc.perform(post("/api/races/r/runners/b/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"tb3","checkpointCode":"p3","elapsedMillis":800,
                                 "expectedVersion":4,"requestId":"c4"}
                                """))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.position").value(3))
                .andExpect(jsonPath("$.elapsedMillis").value(800));
        mockMvc.perform(post("/api/races/r/runners/b/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"tb1","checkpointCode":"p1","elapsedMillis":100,
                                 "expectedVersion":5,"requestId":"c5"}
                                """))
                .andExpect(status().isCreated());

        // 相邻约束违反 422：p2=900 不严格小于已有 p3=800
        mockMvc.perform(post("/api/races/r/runners/b/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"tb2bad","checkpointCode":"p2","elapsedMillis":900,
                                 "expectedVersion":6,"requestId":"c6bad"}
                                """))
                .andExpect(status().isUnprocessableEntity())
                .andExpect(jsonPath("$.error").value("UNPROCESSABLE_ENTITY"));

        // 合法 p2=450
        mockMvc.perform(post("/api/races/r/runners/b/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"tb2","checkpointCode":"p2","elapsedMillis":450,
                                 "expectedVersion":6,"requestId":"c6"}
                                """))
                .andExpect(status().isCreated());

        // a 只过 p1，漏 p2/p3：即使完赛更快也 MISSING_CHECKPOINT 不排名
        mockMvc.perform(post("/api/races/r/runners/a/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"ta1","checkpointCode":"p1","elapsedMillis":100,
                                 "expectedVersion":7,"requestId":"c7"}
                                """))
                .andExpect(status().isCreated());

        mockMvc.perform(get("/api/races/r/results"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(8))
                .andExpect(jsonPath("$.entries[0].bib").value("b"))
                .andExpect(jsonPath("$.entries[0].status").value("RANKED"))
                .andExpect(jsonPath("$.entries[0].rank").value(1))
                .andExpect(jsonPath("$.entries[1].bib").value("a"))
                .andExpect(jsonPath("$.entries[1].status").value("MISSING_CHECKPOINT"))
                .andExpect(jsonPath("$.entries[1].rank").doesNotExist())
                .andExpect(jsonPath("$.entries[1].missingCheckpoints[0]").value("p2"))
                .andExpect(jsonPath("$.entries[1].missingCheckpoints[1]").value("p3"));

        // 单选手分段查询（顺序稳定，缺项 elapsedMillis 缺省）
        mockMvc.perform(get("/api/races/r/runners/a/timings"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.checkpoints.length()").value(3))
                .andExpect(jsonPath("$.checkpoints[0].checkpointCode").value("p1"))
                .andExpect(jsonPath("$.checkpoints[0].elapsedMillis").value(100))
                .andExpect(jsonPath("$.checkpoints[1].elapsedMillis").doesNotExist());

        // 缺失检查点汇总
        mockMvc.perform(get("/api/races/r/missing-checkpoints"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.checkpointCount").value(3))
                .andExpect(jsonPath("$.runners[0].bib").value("a"))
                .andExpect(jsonPath("$.runners[0].missingCheckpoints.length()").value(2))
                .andExpect(jsonPath("$.runners[1].bib").value("b"))
                .andExpect(jsonPath("$.runners[1].missingCheckpoints.length()").value(0));

        // 封榜（expectedVersion=8 -> 9）
        mockMvc.perform(post("/api/races/r/seal")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"expectedVersion":8,"requestId":"c8"}
                                """))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("SEALED"))
                .andExpect(jsonPath("$.version").value(9));

        // 封榜后分段查询走快照，仍保留 a 缺失 p2/p3
        mockMvc.perform(get("/api/races/r/runners/a/timings"))
                .andExpect(jsonPath("$.checkpoints[2].elapsedMillis").doesNotExist());
        mockMvc.perform(get("/api/races/r/missing-checkpoints"))
                .andExpect(jsonPath("$.runners[0].missingCheckpoints.length()").value(2));

        // 封榜后新增分段 409
        mockMvc.perform(post("/api/races/r/runners/a/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"late","checkpointCode":"p2","elapsedMillis":200,
                                 "expectedVersion":9,"requestId":"c9"}
                                """))
                .andExpect(status().isConflict());
    }

    @Test
    void timingId异参返回409且配置校验400() throws Exception {
        mockMvc.perform(post("/api/races")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"raceId":"r2","requestId":"d0"}
                                """))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/races/r2/runners")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"bib":"a","finishTimeMs":9000,"expectedVersion":1,"requestId":"d1"}
                                """))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/races/r2/checkpoints")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"checkpoints":[{"checkpointCode":"p1","position":1}],
                                 "expectedVersion":2,"requestId":"d2"}
                                """))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/races/r2/runners/a/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"dup","checkpointCode":"p1","elapsedMillis":100,
                                 "expectedVersion":3,"requestId":"d3"}
                                """))
                .andExpect(status().isCreated());
        // 同 timingId 不同参数 -> 409
        mockMvc.perform(post("/api/races/r2/runners/a/timings")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"timingId":"dup","checkpointCode":"p1","elapsedMillis":200,
                                 "expectedVersion":3,"requestId":"d4"}
                                """))
                .andExpect(status().isConflict());

        // position 非连续 -> 400
        mockMvc.perform(post("/api/races")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"raceId":"r3","requestId":"e0"}
                                """))
                .andExpect(status().isCreated());
        mockMvc.perform(post("/api/races/r3/checkpoints")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"checkpoints":[
                                  {"checkpointCode":"x","position":1},
                                  {"checkpointCode":"y","position":3}],
                                 "expectedVersion":1,"requestId":"e1"}
                                """))
                .andExpect(status().isBadRequest());
    }
}

