package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 登记医疗暂停请求；暂停区间起止均按 UTC Unix 毫秒时间戳、左闭右开解释。
 *
 * @param holdId          全局唯一医疗暂停ID
 * @param startAt         声明的暂停开始时刻，Unix毫秒时间戳（UTC），区间左闭
 * @param reason          医疗暂停原因（登记后固化不可改写）
 * @param medicalRole     登记暂停的医疗角色标识
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（写操作幂等键）
 */
public record StartMedicalHoldRequest(
        @NotBlank String holdId,
        @NotNull Long startAt,
        @NotBlank @Size(max = 512) String reason,
        @NotBlank String medicalRole,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 恢复适赛（结束医疗暂停）请求；必须由与登记暂停不同的医疗角色确认。
 *
 * @param endAt             声明的暂停结束时刻，Unix毫秒时间戳（UTC），区间右开，必须晚于开始时刻
 * @param fitnessConclusion 适赛结论（恢复后固化不可改写）
 * @param medicalRole       确认适赛的医疗角色标识，必须与登记暂停的角色不同
 * @param expectedVersion   客户端所见赛事版本
 * @param requestId         全局唯一请求ID（写操作幂等键）
 */
public record ResumeMedicalHoldRequest(
        @NotNull Long endAt,
        @NotBlank @Size(max = 512) String fitnessConclusion,
        @NotBlank String medicalRole,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 选手退赛请求；退赛后状态 WITHDRAWN，不排名，不可开始或恢复医疗暂停。
 *
 * @param reason          退赛原因（可选，登记后固化）
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（写操作幂等键）
 */
public record WithdrawRunnerRequest(
        @Size(max = 512) String reason,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 医疗暂停历史查询响应：按登记时间与暂停ID稳定排列；只读，不修改任何状态。
 *
 * @param raceId  赛事ID
 * @param bib     限定查询的参赛号；赛事级查询为 null
 * @param version 查询时的赛事版本（只读查询不修改版本）
 * @param holds   医疗暂停历史明细
 */
public record MedicalHoldHistoryResponse(
        String raceId,
        String bib,
        int version,
        List<MedicalHoldResponse> holds
) {
}

