package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 选手信息响应。
 *
 * @param bib          参赛号
 * @param finishTimeMs 原始完赛耗时毫秒；计时缺失为 null
 * @param withdrawn    是否已退赛
 * @param withdrawnAt  退赛登记时间，Unix毫秒时间戳；未退赛为 null
 * @param createdAt    登记时间，Unix毫秒时间戳
 * @param updatedAt    最近计时修订时间，Unix毫秒时间戳
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record RunnerResponse(
        String bib,
        Long finishTimeMs,
        boolean withdrawn,
        Long withdrawnAt,
        long createdAt,
        long updatedAt
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 分段通过记录响应。
 *
 * @param timingId       全局唯一分段记录ID
 * @param bib            选手参赛号
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序
 * @param elapsedMillis  通过该检查点的累计耗时（毫秒）
 * @param medicalHold    提交时选手是否处于生效医疗暂停：true 为被排除计时，不参与排名
 * @param holdId         排除该计时的医疗暂停ID；未被排除为 null
 * @param createdAt      提交时间，Unix毫秒时间戳
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CheckpointTimingResponse(
        String timingId,
        String bib,
        String checkpointCode,
        int position,
        long elapsedMillis,
        boolean medicalHold,
        String holdId,
        long createdAt
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单个选手在单个检查点上的分段明细。
 *
 * @param checkpointCode  检查点代码
 * @param position        检查点顺序，从1连续递增
 * @param elapsedMillis   通过累计耗时（毫秒）；尚未通过（缺失检查点）为 null
 * @param timingId        分段记录ID；尚未通过为 null
 * @param exclusionReason 该计时被排除的原因（MEDICAL_HOLD-医疗暂停排除）；未排除或缺失为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CheckpointPassResponse(
        String checkpointCode,
        int position,
        Long elapsedMillis,
        String timingId,
        String exclusionReason
) {
}

